import{_ as a,o as n,c as t,a2 as s}from"./chunks/framework.Dp0m3YJZ.js";const b=JSON.parse('{"title":"02 · 開機流程","description":"","frontmatter":{},"headers":[],"relativePath":"topics/boot.md","filePath":"topics/boot.md","lastUpdated":null}'),o={name:"topics/boot.md"};function r(c,e,l,p,i,d){return n(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="_02-·-開機流程" tabindex="-1">02 · 開機流程 <a class="header-anchor" href="#_02-·-開機流程" aria-label="Permalink to &quot;02 · 開機流程&quot;">​</a></h1><p>CPU 不認識 <code>entry.S</code> 或 <code>main.c</code> 這些檔名，只會執行記憶體中的機器指令。兩個來源檔最後會被連結到同一份核心映像。</p><h2 id="從韌體到-c" tabindex="-1">從韌體到 C <a class="header-anchor" href="#從韌體到-c" aria-label="Permalink to &quot;從韌體到 C&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>QEMU virt → OpenSBI → 0x80200000 的 _start</span></span>
<span class="line"><span>  → 設定 stack、清除 BSS → call kernel_main</span></span>
<span class="line"><span>  → 裝置／頁表／檔案系統／行程初始化</span></span>
<span class="line"><span>  → sret → 使用者入口 → shell</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>OpenSBI（RISC-V 韌體）完成早期準備，將控制權交給 S-mode（監督模式）核心。<code>kernel/linker.ld</code> 指定 <code>_start</code> 為入口，從 <code>0x80200000</code> 放置核心。</p><h2 id="entry-s-先準備-c-所需的環境" tabindex="-1">entry.S：先準備 C 所需的環境 <a class="header-anchor" href="#entry-s-先準備-c-所需的環境" aria-label="Permalink to &quot;entry.S：先準備 C 所需的環境&quot;">​</a></h2><p>原始碼：<a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/entry.S" target="_blank" rel="noreferrer">kernel/entry.S（GitHub）</a>。</p><p><code>la sp, __stack_top</code> 設定 sp（堆疊指標）。C 的函式呼叫與區域資料會用到堆疊，因此必須先準備它。</p><p><code>1:</code> 到 <code>2:</code> 的迴圈逐 byte 清除 BSS（未明確指定初值的靜態資料區）。例如 PCB 陣列與頁面管理欄位會從零開始。清除 B 個 bytes 的成本是 O(B)，不另外配置記憶體。</p><p><code>call kernel_main</code> 才是兩個檔案的接點：組合語言以函式呼叫進入 C。若 C 意外返回，後面的 WFI（等待中斷指令）迴圈阻止 CPU 繼續執行未知內容。</p><h2 id="main-c-把子系統串起來" tabindex="-1">main.c：把子系統串起來 <a class="header-anchor" href="#main-c-把子系統串起來" aria-label="Permalink to &quot;main.c：把子系統串起來&quot;">​</a></h2><p>原始碼：<a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/main.c" target="_blank" rel="noreferrer">kernel/main.c（GitHub）</a>。連結為已提交版本，最新未提交裝置初始化調整不會隨文件發布。</p><p>先安裝 trap（陷阱／例外入口），再顯示動畫、探索區塊裝置、建立核心分頁映射與掛載檔案系統。最後建立第一個行程並交給行程恢復流程。</p><p><code>fdt</code> 指向 FDT（硬體裝置樹），是韌體交給核心的硬體描述資料。核心用它尋找 VirtIO 裝置，實體頁配置器也會保留它占用的記憶體。</p><h2 id="開機動畫與觀察" tabindex="-1">開機動畫與觀察 <a class="header-anchor" href="#開機動畫與觀察" aria-label="Permalink to &quot;開機動畫與觀察&quot;">​</a></h2><p><code>kernel/splash.c</code> 透過 UART 輸出 ANSI 終端控制碼，以圖案中點為中心逐欄揭露 WUWAOS。這時尚未進入使用者模式；動畫中的忙等不是排程器，也不代表已啟用計時器中斷。</p><p>執行 <code>make run</code>，應依序看到字樣、核心與裝置資訊、最後的 <code>wuwaos&gt;</code>。<code>/boot/kernel.elf</code> 是 WUFS 中的副本；目前真正啟動核心仍由 QEMU 的 <code>-kernel</code> 載入。</p><h2 id="延伸資料" tabindex="-1">延伸資料 <a class="header-anchor" href="#延伸資料" aria-label="Permalink to &quot;延伸資料&quot;">​</a></h2><p>觀念參考：<code>notes/ch2 Operating-System Structures.md</code> 的開機與核心結構。實作細節與早期動畫驗收見<a href="./../CODE_GUIDE.html">程式碼導覽</a>及 <a href="./../SPEC-04-boot-splash.html">Spec 04</a>。</p>`,19)])])}const m=a(o,[["render",r]]);export{b as __pageData,m as default};
